package main

import (
	"regexp"
	"strings"
)

var ansiRegexp = regexp.MustCompile("\x1b\\[[0-9;]*[a-zA-Z]")

type ANSISpan struct {
	Text string
	Seq  string
}

type Line struct {
	raw            string
	display        string
	displayPlain   string
	output         string
	bufIndex       int
	ansiSpans      []ANSISpan
	isContext      bool
}

func NewLine(raw string, bufIndex int, enableNull, enableANSI bool) Line {
	var display, output string
	if enableNull {
		idx := strings.IndexByte(raw, 0)
		if idx >= 0 {
			display = raw[:idx]
			output = raw[idx+1:]
		} else {
			display = raw
			output = raw
		}
	} else {
		display = raw
		output = raw
	}

	displayPlain := display
	var spans []ANSISpan
	if enableANSI {
		displayPlain = ansiRegexp.ReplaceAllString(display, "")
		// Parse ansi spans for rendering if needed
		spans = parseANSISpans(display)
	}

	return Line{
		raw:          raw,
		display:      display,
		displayPlain: displayPlain,
		output:       output,
		bufIndex:     bufIndex,
		ansiSpans:    spans,
		isContext:    false,
	}
}

func parseANSISpans(s string) []ANSISpan {
	locs := ansiRegexp.FindAllStringIndex(s, -1)
	if len(locs) == 0 {
		return []ANSISpan{{Text: s, Seq: ""}}
	}

	var spans []ANSISpan
	last := 0
	currentSeq := ""
	for _, loc := range locs {
		if loc[0] > last {
			spans = append(spans, ANSISpan{
				Text: s[last:loc[0]],
				Seq:  currentSeq,
			})
		}
		currentSeq = s[loc[0]:loc[1]]
		last = loc[1]
	}
	if last < len(s) {
		spans = append(spans, ANSISpan{
			Text: s[last:],
			Seq:  currentSeq,
		})
	}
	return spans
}
