{"command":"cat <<'EOF' > buffer.go
package main

import (
	"bufio"
	"io"
	"os"
	"strings"
)

type Buffer struct {
	lines      []Line
	maxSize    int
	enableNull bool
	enableANSI bool
	totalRead  int
}

func NewBuffer(maxSize int, enableNull, enableANSI bool) *Buffer {
	return &Buffer{
		lines:      make([]Line, 0, 1024),
		maxSize:    maxSize,
		enableNull: enableNull,
		enableANSI: enableANSI,
	}
}

func (b *Buffer) ReadFrom(r io.Reader) error {
	reader := bufio.NewReader(r)
	for {
		lineStr, err := reader.ReadString('\n')
		if len(lineStr) > 0 {
			lineStr = strings.TrimSuffix(lineStr, "\n")
			lineStr = strings.TrimSuffix(lineStr, "\r")
			line := NewLine(lineStr, b.totalRead, b.enableNull, b.enableANSI)
			b.totalRead++

			if b.maxSize > 0 && len(b.lines) >= b.maxSize {
				b.lines = b.lines[1:]
			}
			b.lines = append(b.lines, line)
		}
		if err != nil {
			if err == io.EOF {
				break
			}
			return err
		}
	}
	return nil
}

func ReadInput(fileArg string, bufferSize int, enableNull, enableANSI bool) (*Buffer, error) {
	buf := NewBuffer(bufferSize, enableNull, enableANSI)
	var reader io.Reader

	if fileArg != "" && fileArg != "-" {
		f, err := os.Open(fileArg)
		if err != nil {
			return nil, err
		}
		defer f.Close()
		reader = f
	} else {
		reader = os.Stdin
	}

	err := buf.ReadFrom(reader)
	if err != nil {
		return nil, err
	}
	return buf, nil
}
EOF"}

