package main

import (
	"bytes"
	"fmt"
	"os/exec"
	"regexp"
	"sort"
	"strings"
)

type Term struct {
	raw        string
	pattern    string
	isNegative bool
}

func parseQueryTerms(query string) []Term {
	if strings.TrimSpace(query) == "" {
		return nil
	}

	rawFields := strings.Fields(query)
	var terms []Term
	for _, f := range rawFields {
		if f == "-" {
			terms = append(terms, Term{raw: f, pattern: "-", isNegative: false})
		} else if strings.HasPrefix(f, "\\-") {
			terms = append(terms, Term{raw: f, pattern: f[1:], isNegative: false})
		} else if strings.HasPrefix(f, "-") && len(f) > 1 {
			terms = append(terms, Term{raw: f, pattern: f[1:], isNegative: true})
		} else {
			terms = append(terms, Term{raw: f, pattern: f, isNegative: false})
		}
	}
	return terms
}

type MatchRange struct {
	Start int
	End   int
}

type MatchResult struct {
	Line    Line
	Ranges  []MatchRange
	Score   int
}

type Filter interface {
	Name() string
	Filter(lines []Line, query string) []MatchResult
}

type IgnoreCaseFilter struct{}

func (f *IgnoreCaseFilter) Name() string { return "IgnoreCase" }
func (f *IgnoreCaseFilter) Filter(lines []Line, query string) []MatchResult {
	terms := parseQueryTerms(query)
	if len(terms) == 0 {
		res := make([]MatchResult, len(lines))
		for i, l := range lines {
			res[i] = MatchResult{Line: l}
		}
		return res
	}

	var results []MatchResult
	for _, line := range lines {
		target := strings.ToLower(line.displayPlain)
		matched := true
		var ranges []MatchRange

		for _, term := range terms {
			pat := strings.ToLower(term.pattern)
			idx := strings.Index(target, pat)
			if term.isNegative {
				if idx >= 0 {
					matched = false
					break
				}
			} else {
				if idx < 0 {
					matched = false
					break
				}
				ranges = append(ranges, MatchRange{Start: idx, End: idx + len(pat)})
			}
		}

		if matched {
			results = append(results, MatchResult{Line: line, Ranges: ranges})
		}
	}
	return results
}

type CaseSensitiveFilter struct{}

func (f *CaseSensitiveFilter) Name() string { return "CaseSensitive" }
func (f *CaseSensitiveFilter) Filter(lines []Line, query string) []MatchResult {
	terms := parseQueryTerms(query)
	if len(terms) == 0 {
		res := make([]MatchResult, len(lines))
		for i, l := range lines {
			res[i] = MatchResult{Line: l}
		}
		return res
	}

	var results []MatchResult
	for _, line := range lines {
		target := line.displayPlain
		matched := true
		var ranges []MatchRange

		for _, term := range terms {
			idx := strings.Index(target, term.pattern)
			if term.isNegative {
				if idx >= 0 {
					matched = false
					break
				}
			} else {
				if idx < 0 {
					matched = false
					break
				}
				ranges = append(ranges, MatchRange{Start: idx, End: idx + len(term.pattern)})
			}
		}

		if matched {
			results = append(results, MatchResult{Line: line, Ranges: ranges})
		}
	}
	return results
}

type SmartCaseFilter struct{}

func (f *SmartCaseFilter) Name() string { return "SmartCase" }
func (f *SmartCaseFilter) Filter(lines []Line, query string) []MatchResult {
	hasUpper := false
	for _, r := range query {
		if r >= 'A' && r <= 'Z' {
			hasUpper = true
			break
		}
	}

	if hasUpper {
		return (&CaseSensitiveFilter{}).Filter(lines, query)
	}
	return (&IgnoreCaseFilter{}).Filter(lines, query)
}

type RegexpFilter struct {
	ignoreCase bool
}

func (f *RegexpFilter) Name() string {
	if f.ignoreCase {
		return "IRegexp"
	}
	return "Regexp"
}

func (f *RegexpFilter) Filter(lines []Line, query string) []MatchResult {
	terms := parseQueryTerms(query)
	if len(terms) == 0 {
		res := make([]MatchResult, len(lines))
		for i, l := range lines {
			res[i] = MatchResult{Line: l}
		}
		return res
	}

	type compiledTerm struct {
		re         *regexp.Regexp
		isNegative bool
	}
	var compiled []compiledTerm
	for _, term := range terms {
		pat := term.pattern
		if f.ignoreCase {
			pat = "(?i)" + pat
		}
		re, err := regexp.Compile(pat)
		if err != nil {
			return nil
		}
		compiled = append(compiled, compiledTerm{re: re, isNegative: term.isNegative})
	}

	var results []MatchResult
	for _, line := range lines {
		target := line.displayPlain
		matched := true
		var ranges []MatchRange

		for _, ct := range compiled {
			loc := ct.re.FindStringIndex(target)
			if ct.isNegative {
				if loc != nil {
					matched = false
					break
				}
			} else {
				if loc == nil {
					matched = false
					break
				}
				ranges = append(ranges, MatchRange{Start: loc[0], End: loc[1]})
			}
		}

		if matched {
			results = append(results, MatchResult{Line: line, Ranges: ranges})
		}
	}
	return results
}

type FuzzyFilter struct {
	LongestSort bool
}

func (f *FuzzyFilter) Name() string { return "Fuzzy" }

func (f *FuzzyFilter) Filter(lines []Line, query string) []MatchResult {
	terms := parseQueryTerms(query)
	if len(terms) == 0 {
		res := make([]MatchResult, len(lines))
		for i, l := range lines {
			res[i] = MatchResult{Line: l}
		}
		return res
	}

	var results []MatchResult
	for _, line := range lines {
		targetLower := strings.ToLower(line.displayPlain)
		matched := true
		var ranges []MatchRange
		score := 0

		for _, term := range terms {
			patLower := strings.ToLower(term.pattern)
			if term.isNegative {
				if strings.Contains(targetLower, patLower) {
					matched = false
					break
				}
			} else {
				// Fuzzy match
				tIdx := 0
				pIdx := 0
				firstIdx := -1
				lastIdx := -1

				for tIdx < len(targetLower) && pIdx < len(patLower) {
					if targetLower[tIdx] == patLower[pIdx] {
						if firstIdx == -1 {
							firstIdx = tIdx
						}
						lastIdx = tIdx
						ranges = append(ranges, MatchRange{Start: tIdx, End: tIdx + 1})
						pIdx++
					}
					tIdx++
				}

				if pIdx < len(patLower) {
					matched = false
					break
				}

				score += (lastIdx - firstIdx + 1)
			}
		}

		if matched {
			results = append(results, MatchResult{Line: line, Ranges: ranges, Score: score})
		}
	}

	if f.LongestSort {
		sort.SliceStable(results, func(i, j int) bool {
			return results[i].Score < results[j].Score
		})
	}

	return results
}

