package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"gopkg.in/yaml.v3"
)

type CustomFilterConfig struct {
	Cmd             string   `json:"Cmd" yaml:"Cmd"`
	Args            []string `json:"Args" yaml:"Args"`
	BufferThreshold int      `json:"BufferThreshold" yaml:"BufferThreshold"`
}

type SingleKeyJumpConfig struct {
	ShowPrefix bool `json:"ShowPrefix" yaml:"ShowPrefix"`
}

type Config struct {
	Prompt           string                        `json:"Prompt" yaml:"Prompt"`
	InitialFilter    string                        `json:"InitialFilter" yaml:"InitialFilter"`
	FuzzyLongestSort bool                          `json:"FuzzyLongestSort" yaml:"FuzzyLongestSort"`
	StickySelection  bool                          `json:"StickySelection" yaml:"StickySelection"`
	Layout           string                        `json:"Layout" yaml:"Layout"`
	SelectionPrefix  string                        `json:"SelectionPrefix" yaml:"SelectionPrefix"`
	OnCancel         string                        `json:"OnCancel" yaml:"OnCancel"`
	ANSI             bool                          `json:"ANSI" yaml:"ANSI"`
	SingleKeyJump    SingleKeyJumpConfig           `json:"SingleKeyJump" yaml:"SingleKeyJump"`
	CustomFilter     map[string]CustomFilterConfig `json:"CustomFilter" yaml:"CustomFilter"`
	Style            map[string][]string           `json:"Style" yaml:"Style"`
	Keymap           map[string]interface{}        `json:"Keymap" yaml:"Keymap"`
}

func NewDefaultConfig() *Config {
	return &Config{
		Prompt:          "QUERY>",
		InitialFilter:   "IgnoreCase",
		Layout:          "top-down",
		OnCancel:        "success",
		CustomFilter:    make(map[string]CustomFilterConfig),
		Style: map[string][]string{
			"Basic":          {"on_default", "default"},
			"SavedSelection": {"bold", "on_yellow", "white"},
			"Selected":       {"underline", "on_cyan", "black"},
			"Query":          {"yellow", "bold"},
			"QueryCursor":    {"white", "on_red"},
			"Matched":        {"red", "on_blue"},
			"Prompt":         {"green", "bold"},
			"Context":        {"bold"},
		},
		Keymap: make(map[string]interface{}),
	}
}

func LoadConfig(rcfile string) (*Config, error) {
	cfg := NewDefaultConfig()

	var filesToTry []string
	if rcfile != "" {
		filesToTry = []string{rcfile}
	} else {
		xdgConfigHome := os.Getenv("XDG_CONFIG_HOME")
		home := os.Getenv("HOME")
		xdgConfigDirs := os.Getenv("XDG_CONFIG_DIRS")

		if xdgConfigHome != "" {
			filesToTry = append(filesToTry,
				filepath.Join(xdgConfigHome, "peco", "config.json"),
				filepath.Join(xdgConfigHome, "peco", "config.yaml"),
			)
		} else if home != "" {
			filesToTry = append(filesToTry,
				filepath.Join(home, ".config", "peco", "config.json"),
				filepath.Join(home, ".config", "peco", "config.yaml"),
			)
		}

		if xdgConfigDirs != "" {
			for _, d := range filepath.SplitList(xdgConfigDirs) {
				filesToTry = append(filesToTry,
					filepath.Join(d, "peco", "config.json"),
					filepath.Join(d, "peco", "config.yaml"),
				)
			}
		}

		if home != "" {
			filesToTry = append(filesToTry,
				filepath.Join(home, ".peco", "config.json"),
				filepath.Join(home, ".peco", "config.yaml"),
			)
		}
	}

	var foundFile string
	for _, f := range filesToTry {
		if _, err := os.Stat(f); err == nil {
			foundFile = f
			break
		}
	}

	if rcfile != "" && foundFile == "" {
		return nil, fmt.Errorf("failed to open file %s: open %s: no such file or directory", rcfile, rcfile)
	}

	if foundFile != "" {
		data, err := os.ReadFile(foundFile)
		if err != nil {
			return nil, fmt.Errorf("failed to open file %s: %w", foundFile, err)
		}

		isYAML := strings.HasSuffix(foundFile, ".yaml") || strings.HasSuffix(foundFile, ".yml")

		var fileCfg Config
		if isYAML {
			err = yaml.Unmarshal(data, &fileCfg)
			if err != nil {
				return nil, fmt.Errorf("failed to decode YAML: %w", err)
			}
		} else {
			// Try JSON unmarshal first
			err = json.Unmarshal(data, &fileCfg)
			if err != nil {
				// Try YAML unmarshal
				errYaml := yaml.Unmarshal(data, &fileCfg)
				if errYaml != nil {
					return nil, fmt.Errorf("failed to decode JSON: %w", err)
				}
			}
		}

		cfg.merge(&fileCfg)
	}

	if cfg.OnCancel != "success" && cfg.OnCancel != "error" {
		return nil, fmt.Errorf("invalid OnCancel value %q: must be \"success\" or \"error\"", cfg.OnCancel)
	}

	return cfg, nil
}

func (c *Config) merge(other *Config) {
	if other.Prompt != "" {
		c.Prompt = other.Prompt
	}
	if other.InitialFilter != "" {
		c.InitialFilter = other.InitialFilter
	}
	if other.Layout != "" {
		c.Layout = other.Layout
	}
	if other.SelectionPrefix != "" {
		c.SelectionPrefix = other.SelectionPrefix
	}
	if other.OnCancel != "" {
		c.OnCancel = other.OnCancel
	}
	if other.FuzzyLongestSort {
		c.FuzzyLongestSort = true
	}
	if other.StickySelection {
		c.StickySelection = true
	}
	if other.ANSI {
		c.ANSI = true
	}
	if other.SingleKeyJump.ShowPrefix {
		c.SingleKeyJump.ShowPrefix = true
	}

	for k, v := range other.CustomFilter {
		c.CustomFilter[k] = v
	}
	for k, v := range other.Style {
		c.Style[k] = v
	}
	for k, v := range other.Keymap {
		c.Keymap[k] = v
	}
}
EOF"}

