	Selected       tcell.Style
	Query          tcell.Style
	QueryCursor    tcell.Style
	Matched        tcell.Style
	Prompt         tcell.Style
	Context        tcell.Style
}

func parseColor(colorStr string, isBg bool) (tcell.Color, tcell.AttrMask) {
	if isBg {
		colorStr = strings.TrimPrefix(colorStr, "on_")
	}

	attr := tcell.AttrNone
	if colorStr == "bold" {
		return tcell.ColorDefault, tcell.AttrBold
	}
	if colorStr == "underline" {
		return tcell.ColorDefault, tcell.AttrUnderline
	}
	if colorStr == "reverse" {
		return tcell.ColorDefault, tcell.AttrReverse
	}

	switch colorStr {
	case "default":
		return tcell.ColorDefault, attr
	case "black":
		return tcell.ColorBlack, attr
	case "red":
		return tcell.ColorMaroon, attr
	case "green":
		return tcell.ColorGreen, attr
	case "yellow":
		return tcell.ColorOlive, attr
	case "blue":
		return tcell.ColorNavy, attr
	case "magenta":
		return tcell.ColorPurple, attr
	case "cyan":
		return tcell.ColorTeal, attr
	case "white":
		return tcell.ColorSilver, attr
	}

	// Try 256color int
	if num, err := strconv.Atoi(colorStr); err == nil && num >= 0 && num <= 255 {
		return tcell.PaletteColor(num), attr
	}

	// Try hex #RRGGBB
	if strings.HasPrefix(colorStr, "#") && len(colorStr) == 7 {
		return tcell.GetColor(colorStr), attr
	}

	return tcell.ColorDefault, attr
}

func parseStyle(specs []string) tcell.Style {
	style := tcell.StyleDefault
	for _, spec := range specs {
		if strings.HasPrefix(spec, "on_") {
			color, attr := parseColor(spec, true)
			style = style.Background(color).Attributes(attr)
		} else {
			color, attr := parseColor(spec, false)
			if attr != tcell.AttrNone {
				style = style.Attributes(attr)
			} else {
				style = style.Foreground(color)
			}
		}
	}
	return style
}

func NewStyleMap(cfgStyle map[string][]string) StyleMap {
	sm := StyleMap{
		Basic:          tcell.StyleDefault,
		SavedSelection: tcell.StyleDefault.Attributes(tcell.AttrBold).Background(tcell.ColorYellow).Foreground(tcell.ColorWhite),
		Selected:       tcell.StyleDefault.Attributes(tcell.AttrUnderline).Background(tcell.ColorTeal).Foreground(tcell.ColorBlack),
		Query:          tcell.StyleDefault.Foreground(tcell.ColorYellow).Attributes(tcell.AttrBold),
		QueryCursor:    tcell.StyleDefault.Foreground(tcell.ColorWhite).Background(tcell.ColorMaroon),
		Matched:        tcell.StyleDefault.Foreground(tcell.ColorMaroon).Background(tcell.ColorNavy),
		Prompt:         tcell.StyleDefault.Foreground(tcell.ColorGreen).Attributes(tcell.AttrBold),
		Context:        tcell.StyleDefault.Attributes(tcell.AttrBold),
	}

	if specs, ok := cfgStyle["Basic"]; ok {
		sm.Basic = parseStyle(specs)
	}
	if specs, ok := cfgStyle["SavedSelection"]; ok {
		sm.SavedSelection = parseStyle(specs)
	}
	if specs, ok := cfgStyle["Selected"]; ok {
		sm.Selected = parseStyle(specs)
	}
	if specs, ok := cfgStyle["Query"]; ok {
		sm.Query = parseStyle(specs)
	}
	if specs, ok := cfgStyle["QueryCursor"]; ok {
		sm.QueryCursor = parseStyle(specs)
	}
	if specs, ok := cfgStyle["Matched"]; ok {
		sm.Matched = parseStyle(specs)
	}
	if specs, ok := cfgStyle["Prompt"]; ok {
		sm.Prompt = parseStyle(specs)
	}
	if specs, ok := cfgStyle["Context"]; ok {
		sm.Context = parseStyle(specs)
	}

	return sm
}

func drawString(s tcell.Screen, x, y int, str string, style tcell.Style) int {
	for _, r := range str {
		w := runewidth.RuneWidth(r)
		s.SetContent(x, y, r, nil, style)
		x += w
	}
	return x
}
EOF"}

