{"command":"cat <<'EOF' > app.go
package main

import (
	"fmt"
	"os"
	"os/exec"
	"strconv"

	"github.com/gdamore/tcell/v2"
	"github.com/mattn/go-runewidth"
)

type App struct {
	config          *Config
	keymap          *Keymap
	styles          StyleMap
	buffer          *Buffer
	screen          tcell.Screen
	query           string
	caretPos        int
	filters         []Filter
	filterIdx       int
	filtered        []MatchResult
	selection       map[int]bool
	selectionCursor int
	scrollOffset    int
	frozenStack     [][]Line
	zoom            bool
	singleKeyJump   bool
	singleKeyLabels []string
	statusMsg       string
	finishOutput    []string
	cancelled       bool
	exitCode        int
	height          string
	execCmd         string
	printQuery      bool
	selectionPrefix string
	queryMode       bool
}

func NewApp(cfg *Config, keymap *Keymap, buf *Buffer, height, execCmd string, printQuery bool, selPrefix string) *App {
	jumpKeys := []string{"a", "s", "d", "f", "g", "h", "j", "k", "l", "z", "x", "c", "v", "b", "n", "m", "q", "w", "e", "r", "t", "y", "u", "i", "o", "p"}

	app := &App{
		config:          cfg,
		keymap:          keymap,
		styles:          NewStyleMap(cfg.Style),
		buffer:          buf,
		selection:       make(map[int]bool),
		singleKeyLabels: jumpKeys,
		height:          height,
		execCmd:         execCmd,
		printQuery:      printQuery,
		selectionPrefix: selPrefix,
		queryMode:       true,
	}

	if selPrefix == "" && cfg.SelectionPrefix != "" {
		app.selectionPrefix = cfg.SelectionPrefix
	}

	// Initialize filters
	app.filters = []Filter{
		&IgnoreCaseFilter{},
		&CaseSensitiveFilter{},
		&SmartCaseFilter{},
		&RegexpFilter{ignoreCase: true},
		&RegexpFilter{ignoreCase: false},
		&FuzzyFilter{LongestSort: cfg.FuzzyLongestSort},
	}

	for k, cfc := range cfg.CustomFilter {
		cf := &CustomFilterDef{
			name:            k,
			cmd:             cfc.Cmd,
			args:            cfc.Args,
			bufferThreshold: cfc.BufferThreshold,
		}
		app.filters = append(app.filters, cf)
	}

	// Find initial filter
	initFilterName := cfg.InitialFilter
	if initFilterName != "" {
		found := false
		for i, f := range app.filters {
			if f.Name() == initFilterName {
				app.filterIdx = i
				found = true
				break
			}
		}
		if !found {
			// Specified filter not found
		}
	}

	return app
}

func (a *App) activeLines() []Line {
	if len(a.frozenStack) > 0 {
		return a.frozenStack[len(a.frozenStack)-1]
	}
	return a.buffer.lines
}

func (a *App) updateFilter() {
	if !a.queryMode {
		lines := a.activeLines()
		res := make([]MatchResult, len(lines))
		for i, l := range lines {
			res[i] = MatchResult{Line: l}
		}
		a.filtered = res
		return
	}

	f := a.filters[a.filterIdx]
	a.filtered = f.Filter(a.activeLines(), a.query)

	if a.selectionCursor >= len(a.filtered) {
		if len(a.filtered) > 0 {
			a.selectionCursor = len(a.filtered) - 1
		} else {
			a.selectionCursor = 0
		}
	}
}

func (a *App) currentFilter() Filter {
	return a.filters[a.filterIdx]
}

func (a *App) moveCaret(delta int) {
	runes := []rune(a.query)
	newPos := a.caretPos + delta
	if newPos < 0 {
		newPos = 0
	}
	if newPos > len(runes) {
		newPos = len(runes)
	}
	a.caretPos = newPos
}

func (a *App) moveWord(dir int) {
	runes := []rune(a.query)
	pos := a.caretPos
	if dir < 0 {
		for pos > 0 && runes[pos-1] == ' ' {
			pos--
		}
		for pos > 0 && runes[pos-1] != ' ' {
			pos--
		}
	} else {
		for pos < len(runes) && runes[pos] != ' ' {
			pos++
		}
		for pos < len(runes) && runes[pos] == ' ' {
			pos++
		}
	}
	a.caretPos = pos
}

func (a *App) deleteChar(dir int) {
	runes := []rune(a.query)
	if dir < 0 {
		if a.caretPos > 0 {
			a.query = string(runes[:a.caretPos-1]) + string(runes[a.caretPos:])
			a.caretPos--
			a.updateFilter()
		}
	} else {
		if a.caretPos < len(runes) {
			a.query = string(runes[:a.caretPos]) + string(runes[a.caretPos+1:])
			a.updateFilter()
		}
	}
}

func (a *App) deleteWord(dir int) {
	runes := []rune(a.query)
	oldPos := a.caretPos
	a.moveWord(dir)
	newPos := a.caretPos
	if oldPos > newPos {
		a.query = string(runes[:newPos]) + string(runes[oldPos:])
		a.caretPos = newPos
	} else if oldPos < newPos {
		a.query = string(runes[:oldPos]) + string(runes[newPos:])
		a.caretPos = oldPos
	}
	a.updateFilter()
}

func (a *App) moveSelection(delta int) {
	if len(a.filtered) == 0 {
		return
	}
	newCursor := a.selectionCursor + delta
	if newCursor < 0 {
		newCursor = 0
	}
	if newCursor >= len(a.filtered) {
		newCursor = len(a.filtered) - 1
	}
	a.selectionCursor = newCursor
}

func (a *App) toggleSelectionCurrent() {
	if len(a.filtered) == 0 || a.selectionCursor >= len(a.filtered) {
		return
	}
	bufIdx := a.filtered[a.selectionCursor].Line.bufIndex
	if a.selection[bufIdx] {
		delete(a.selection, bufIdx)
	} else {
		a.selection[bufIdx] = true
	}
}

func (a *App) selectAllMatched() {
	for _, m := range a.filtered {
		a.selection[m.Line.bufIndex] = true
	}
}

func (a *App) selectNone() {
	a.selection = make(map[int]bool)
}

func (a *App) invertSelection() {
	for _, m := range a.filtered {
		bufIdx := m.Line.bufIndex
		if a.selection[bufIdx] {
			delete(a.selection, bufIdx)
		} else {
			a.selection[bufIdx] = true
		}
	}
}

func (a *App) rotateFilter() {
	a.filterIdx = (a.filterIdx + 1) % len(a.filters)
	a.updateFilter()
}

func (a *App) resetFilter() {
	a.filterIdx = 0
	a.updateFilter()
}

func (a *App) toggleQuery() {
	a.queryMode = !a.queryMode
	a.updateFilter()
}

func (a *App) freezeResults() {
	var currentLines []Line
	for _, m := range a.filtered {
		currentLines = append(currentLines, m.Line)
	}
