}

func NewApp(cfg *Config, keymap *Keymap, buf *Buffer, height, execCmd string, printQuery bool, selPrefix string) *App {
	jumpKeys := []string{"a", "s", "d", "f", "g", "h", "j", "k", "l", "z", "x", "c", "v", "b", "n", "m", "q", "w", "e", "r", "t", "y", "u", "i", "o", "p"}

	app := &App{
		config:          cfg,
