		height:          height,
		execCmd:         execCmd,
		printQuery:      printQuery,
		selectionPrefix: selPrefix,
		queryMode:       true,
	}

	if selPrefix == "" && cfg.SelectionPrefix != "" {
		app.selectionPrefix = cfg.SelectionPrefix
	}

	// Initialize filters
	app.filters = []Filter{
		&IgnoreCaseFilter{},
		&CaseSensitiveFilter{},
		&SmartCaseFilter{},
		&RegexpFilter{ignoreCase: true},
		&RegexpFilter{ignoreCase: false},
		&FuzzyFilter{LongestSort: cfg.FuzzyLongestSort},
	}

	for k, cfc := range cfg.CustomFilter {
		cf := &CustomFilterDef{
			name:            k,
			cmd:             cfc.Cmd,
			args:            cfc.Args,
			bufferThreshold: cfc.BufferThreshold,
		}
		app.filters = append(app.filters, cf)
	}

	// Find initial filter
	initFilterName := cfg.InitialFilter
	if initFilterName != "" {
		found := false
		for i, f := range app.filters {
