	runes := []rune(a.query)
	pos := a.caretPos
	if dir < 0 {
		for pos > 0 && runes[pos-1] == ' ' {
			pos--
		}
		for pos > 0 && runes[pos-1] != ' ' {
			pos--
		}
	} else {
		for pos < len(runes) && runes[pos] != ' ' {
			pos++
		}
		for pos < len(runes) && runes[pos] == ' ' {
