		score := 0

		for _, term := range terms {
			patLower := strings.ToLower(term.pattern)
			if term.isNegative {
				if strings.Contains(targetLower, patLower) {
					matched = false
					break
				}
			} else {
				// Fuzzy match
				tIdx := 0
				pIdx := 0
				firstIdx := -1
				lastIdx := -1

				for tIdx < len(targetLower) && pIdx < len(patLower) {
					if targetLower[tIdx] == patLower[pIdx] {
