				ranges = append(ranges, MatchRange{Start: loc[0], End: loc[1]})
			}
		}

		if matched {
			results = append(results, MatchResult{Line: line, Ranges: ranges})
		}
	}
	return results
}

type FuzzyFilter struct {
	LongestSort bool
}

func (f *FuzzyFilter) Name() string { return "Fuzzy" }

func (f *FuzzyFilter) Filter(lines []Line, query string) []MatchResult {
	terms := parseQueryTerms(query)
	if len(terms) == 0 {
		res := make([]MatchResult, len(lines))
		for i, l := range lines {
			res[i] = MatchResult{Line: l}
		}
		return res
	}

	var results []MatchResult
	for _, line := range lines {
		targetLower := strings.ToLower(line.displayPlain)
		matched := true
		var ranges []MatchRange
		score := 0

		for _, term := range terms {
			patLower := strings.ToLower(term.pattern)
			if term.isNegative {
				if strings.Contains(targetLower, patLower) {
					matched = false
					break
				}
			} else {
				// Fuzzy match
				tIdx := 0
				pIdx := 0
				firstIdx := -1
				lastIdx := -1

				for tIdx < len(targetLower) && pIdx < len(patLower) {
					if targetLower[tIdx] == patLower[pIdx] {
						if firstIdx == -1 {
							firstIdx = tIdx
						}
						lastIdx = tIdx
						ranges = append(ranges, MatchRange{Start: tIdx, End: tIdx + 1})
						pIdx++
					}
					tIdx++
				}

				if pIdx < len(patLower) {
					matched = false
					break
				}

				score += (lastIdx - firstIdx + 1)
			}
		}

		if matched {
			results = append(results, MatchResult{Line: line, Ranges: ranges, Score: score})
		}
	}

	if f.LongestSort {
		sort.SliceStable(results, func(i, j int) bool {
			return results[i].Score < results[j].Score
		})
	}

	return results
}

type CustomFilterDef struct {
	name            string
	cmd             string
	args            []string
	bufferThreshold int
}

func (f *CustomFilterDef) Name() string { return f.name }

func (f *CustomFilterDef) Filter(lines []Line, query string) []MatchResult {
	if len(lines) == 0 {
		return nil
	}

	var inBuf bytes.Buffer
	for _, l := range lines {
		inBuf.WriteString(l.raw)
		inBuf.WriteString("\n")
	}

	var finalArgs []string
	argsTemplate := f.args
	if len(argsTemplate) == 0 {
		argsTemplate = []string{"$QUERY"}
	}
	for _, arg := range argsTemplate {
		finalArgs = append(finalArgs, strings.ReplaceAll(arg, "$QUERY", query))
	}

	cmd := exec.Command(f.cmd, finalArgs...)
	cmd.Stdin = &inBuf
	var outBuf bytes.Buffer
	cmd.Stdout = &outBuf

	err := cmd.Run()
	if err != nil {
		return nil
	}

	outLines := strings.Split(outBuf.String(), "\n")
	outMap := make(map[string]bool)
	for _, ol := range outLines {
		if ol != "" {
			outMap[ol] = true
		}
	}

	var results []MatchResult
	for _, l := range lines {
		if outMap[l.raw] || outMap[l.display] {
			results = append(results, MatchResult{Line: l})
		}
	}
	return results
}
EOF"}

