func (a *App) activeLines() []Line {
	if len(a.frozenStack) > 0 {
		return a.frozenStack[len(a.frozenStack)-1]
	}
	return a.buffer.lines
}

func (a *App) updateFilter() {
	if !a.queryMode {
		lines := a.activeLines()
		res := make([]MatchResult, len(lines))
		for i, l := range lines {
			res[i] = MatchResult{Line: l}
		}
		a.filtered = res
		return
	}

	f := a.filters[a.filterIdx]
	a.filtered = f.Filter(a.activeLines(), a.query)

	if a.selectionCursor >= len(a.filtered) {
		if len(a.filtered) > 0 {
			a.selectionCursor = len(a.filtered) - 1
		} else {
			a.selectionCursor = 0
		}
	}
}

func (a *App) currentFilter() Filter {
	return a.filters[a.filterIdx]
}

func (a *App) moveCaret(delta int) {
	runes := []rune(a.query)
	newPos := a.caretPos + delta
	if newPos < 0 {
		newPos = 0
	}
	if newPos > len(runes) {
		newPos = len(runes)
	}
	a.caretPos = newPos
}

func (a *App) moveWord(dir int) {
	runes := []rune(a.query)
	pos := a.caretPos
	if dir < 0 {
		for pos > 0 && runes[pos-1] == ' ' {
			pos--
		}
		for pos > 0 && runes[pos-1] != ' ' {
			pos--
		}
	} else {
		for pos < len(runes) && runes[pos] != ' ' {
			pos++
		}
		for pos < len(runes) && runes[pos] == ' ' {
			pos++
		}
	}
	a.caretPos = pos
}

func (a *App) deleteChar(dir int) {
	runes := []rune(a.query)
	if dir < 0 {
		if a.caretPos > 0 {
			a.query = string(runes[:a.caretPos-1]) + string(runes[a.caretPos:])
			a.caretPos--
			a.updateFilter()
		}
	} else {
		if a.caretPos < len(runes) {
			a.query = string(runes[:a.caretPos]) + string(runes[a.caretPos+1:])
			a.updateFilter()
		}
	}
}

func (a *App) deleteWord(dir int) {
	runes := []rune(a.query)
	oldPos := a.caretPos
	a.moveWord(dir)
	newPos := a.caretPos
	if oldPos > newPos {
		a.query = string(runes[:newPos]) + string(runes[oldPos:])
		a.caretPos = newPos
	} else if oldPos < newPos {
		a.query = string(runes[:oldPos]) + string(runes[newPos:])
		a.caretPos = oldPos
	}
	a.updateFilter()
}

func (a *App) moveSelection(delta int) {
	if len(a.filtered) == 0 {
		return
	}
	newCursor := a.selectionCursor + delta
	if newCursor < 0 {
		newCursor = 0
	}
	if newCursor >= len(a.filtered) {
		newCursor = len(a.filtered) - 1
	}
	a.selectionCursor = newCursor
}

func (a *App) toggleSelectionCurrent() {
	if len(a.filtered) == 0 || a.selectionCursor >= len(a.filtered) {
		return
	}
	bufIdx := a.filtered[a.selectionCursor].Line.bufIndex
	if a.selection[bufIdx] {
		delete(a.selection, bufIdx)
	} else {
		a.selection[bufIdx] = true
	}
}

func (a *App) selectAllMatched() {
	for _, m := range a.filtered {
		a.selection[m.Line.bufIndex] = true
	}
}

func (a *App) selectNone() {
	a.selection = make(map[int]bool)
}

func (a *App) invertSelection() {
	for _, m := range a.filtered {
		bufIdx := m.Line.bufIndex
		if a.selection[bufIdx] {
			delete(a.selection, bufIdx)
		} else {
			a.selection[bufIdx] = true
		}
	}
}

func (a *App) rotateFilter() {
	a.filterIdx = (a.filterIdx + 1) % len(a.filters)
	a.updateFilter()
}

func (a *App) resetFilter() {
	a.filterIdx = 0
	a.updateFilter()
}

func (a *App) toggleQuery() {
	a.queryMode = !a.queryMode
	a.updateFilter()
}

func (a *App) freezeResults() {
	var currentLines []Line
	for _, m := range a.filtered {
		currentLines = append(currentLines, m.Line)
	}
	a.frozenStack = append(a.frozenStack, currentLines)
	a.query = ""
	a.caretPos = 0
	a.updateFilter()
}

func (a *App) unfreezeResults() {
	if len(a.frozenStack) > 0 {
		a.frozenStack = a.frozenStack[:len(a.frozenStack)-1]
		a.query = ""
		a.caretPos = 0
		a.updateFilter()
	}
}

func (a *App) zoomIn() {
	a.zoom = true
}

func (a *App) zoomOut() {
	a.zoom = false
}

func (a *App) toggleSingleKeyJump() {
	a.singleKeyJump = !a.singleKeyJump
}

func (a *App) pageSize() int {
	_, h := a.screen.Size()
	renderH := a.calculateRenderHeight(h)
	listH := renderH - 2
	if listH < 1 {
		return 1
	}
	return listH
}

func (a *App) calculateRenderHeight(screenHeight int) int {
	if a.height == "" {
		return screenHeight
	}

	if strings.HasSuffix(a.height, "%") {
		pctStr := strings.TrimSuffix(a.height, "%")
		pct, err := strconv.Atoi(pctStr)
		if err == nil && pct > 0 {
			h := screenHeight * pct / 100
			if h < 3 {
				h = 3
			}
			if h > screenHeight {
				h = screenHeight
			}
			return h
		}
	} else {
		num, err := strconv.Atoi(a.height)
		if err == nil && num > 0 {
			h := num + 2
			if h > screenHeight {
				h = screenHeight
			}
			return h
		}
	}
	return screenHeight
}

func (a *App) getSelectedLines() []string {
	if len(a.selection) > 0 {
		var res []string
		for _, line := range a.buffer.lines {
			if a.selection[line.bufIndex] {
				res = append(res, line.output)
			}
		}
		return res
	}

	if len(a.filtered) > 0 && a.selectionCursor < len(a.filtered) {
		return []string{a.filtered[a.selectionCursor].Line.output}
	}

	return nil
}

func (a *App) Finish() {
	selected := a.getSelectedLines()
	if a.execCmd != "" {
		if len(selected) > 0 {
			a.runExec(selected)
		}
		return
	}

	a.finishOutput = selected
	a.cancelled = false
	a.exitCode = 0
	if a.screen != nil {
		a.screen.Fini()
	}
}

func (a *App) Cancel() {
	a.cancelled = true
	if a.config.OnCancel == "error" {
		a.exitCode = 1
	} else {
		a.exitCode = 0
	}
	if a.screen != nil {
		a.screen.Fini()
	}
}

func (a *App) runExec(lines []string) {
	a.screen.Fini()

	cmd := exec.Command("/bin/sh", "-c", a.execCmd)
	cmd.Stdin = strings.NewReader(strings.Join(lines, "\n") + "\n")
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	_ = cmd.Run()

	s, err := tcell.NewScreen()
	if err == nil {
		a.screen = s
		_ = s.Init()
		s.Clear()
	}
}

func (a *App) drawScreen() {
	s := a.screen
	if s == nil {
		return
	}
	s.Clear()

	w, screenH := s.Size()
	renderH := a.calculateRenderHeight(screenH)
	listH := renderH - 2
	if listH < 1 {
		listH = 1
	}

	currentPage := 1
	totalPages := 1
	if len(a.filtered) > 0 {
		totalPages = (len(a.filtered) + listH - 1) / listH
		currentPage = (a.selectionCursor / listH) + 1
	}
	pageStart := (currentPage - 1) * listH

	layout := a.config.Layout
	promptRow := 0
	listStartRow := 1
	statusRow := renderH - 1

	if layout == "bottom-up" {
		listStartRow = 0
		promptRow = renderH - 2
		statusRow = renderH - 1
	} else if layout == "top-down-query-bottom" {
		listStartRow = 0
		promptRow = renderH - 2
		statusRow = renderH - 1
	}

	promptStr := a.config.Prompt
	if promptStr == "" {
		promptStr = "QUERY>"
	}

	filterInfo := fmt.Sprintf("%s [%d (%d/%d)]", a.currentFilter().Name(), len(a.buffer.lines), currentPage, totalPages)

	x := 0
	x = drawString(s, x, promptRow, promptStr, a.styles.Prompt)
	x = drawString(s, x, promptRow, " ", a.styles.Basic)

	qRunes := []rune(a.query)
	for i, r := range qRunes {
		st := a.styles.Query
		if i == a.caretPos {
			st = a.styles.QueryCursor
		}
		s.SetContent(x, promptRow, r, nil, st)
		x += runewidth.RuneWidth(r)
	}
	if a.caretPos == len(qRunes) {
		s.SetContent(x, promptRow, ' ', nil, a.styles.QueryCursor)
		x++
	}

	infoX := w - len(filterInfo)
	if infoX > x+1 {
		drawString(s, infoX, promptRow, filterInfo, a.styles.Basic)
	}

	for i := 0; i < listH; i++ {
		itemIdx := pageStart + i
		rowY := listStartRow + i
		if layout == "bottom-up" {
			rowY = (listStartRow + listH - 1) - i
		}

		if itemIdx >= len(a.filtered) {
			continue
		}

		matchRes := a.filtered[itemIdx]
		line := matchRes.Line
		isFocused := (itemIdx == a.selectionCursor)
		isSaved := a.selection[line.bufIndex]

		baseStyle := a.styles.Basic
		if isSaved {
			baseStyle = a.styles.SavedSelection
		}
		if isFocused {
			baseStyle = a.styles.Selected
		}

		itemX := 0

		if a.singleKeyJump {
			labelIdx := i
			if labelIdx < len(a.singleKeyLabels) {
				lbl := a.singleKeyLabels[labelIdx]
				if a.config.SingleKeyJump.ShowPrefix {
					lbl = "[" + lbl + "]"
				}
				itemX = drawString(s, itemX, rowY, lbl, a.styles.QueryCursor)
				itemX = drawString(s, itemX, rowY, " ", baseStyle)
			}
		} else if a.selectionPrefix != "" {
			if isFocused {
				itemX = drawString(s, itemX, rowY, a.selectionPrefix, baseStyle)
				itemX = drawString(s, itemX, rowY, " ", baseStyle)
			} else {
				spaces := strings.Repeat(" ", runewidth.StringWidth(a.selectionPrefix)+1)
				itemX = drawString(s, itemX, rowY, spaces, baseStyle)
			}
		}

		text := line.displayPlain
		runes := []rune(text)

		matchedMask := make([]bool, len(runes))
		for _, r := range matchRes.Ranges {
			for idx := r.Start; idx < r.End && idx < len(runes); idx++ {
				matchedMask[idx] = true
			}
		}

		for idx, r := range runes {
			if idx < a.scrollOffset {
				continue
			}
			st := baseStyle
			if matchedMask[idx] {
				st = a.styles.Matched
			}
			s.SetContent(itemX, rowY, r, nil, st)
			itemX += runewidth.RuneWidth(r)
			if itemX >= w {
				break
			}
		}

		for fillX := itemX; fillX < w; fillX++ {
			s.SetContent(fillX, rowY, ' ', nil, baseStyle)
		}
	}

	if a.statusMsg != "" {
		drawString(s, 0, statusRow, a.statusMsg, a.styles.Basic)
	}

	s.Show()
}

func (a *App) Run() error {
	s, err := tcell.NewScreen()
	if err != nil {
		return fmt.Errorf("failed to create tcell screen: %w", err)
	}
	if err := s.Init(); err != nil {
		return fmt.Errorf("failed to initialize tcell screen: %w", err)
	}
	a.screen = s

	a.updateFilter()
	a.drawScreen()

	for {
		ev := s.PollEvent()
		if ev == nil {
			break
		}

		switch ev := ev.(type) {
		case *tcell.EventKey:
			keyName := EventToKeyName(ev)

			if a.singleKeyJump {
				if ev.Key() == tcell.KeyEscape {
					a.singleKeyJump = false
					a.drawScreen()
					continue
				}
				if ev.Key() == tcell.KeyRune {
					r := string(ev.Rune())
					listH := a.pageSize()
					pageStart := (a.selectionCursor / listH) * listH
					for i, lbl := range a.singleKeyLabels {
						if lbl == r && i < listH {
							targetIdx := pageStart + i
							if targetIdx < len(a.filtered) {
								a.selectionCursor = targetIdx
								a.singleKeyJump = false
								a.Finish()
								return nil
							}
						}
					}
				}
				a.singleKeyJump = false
				a.drawScreen()
				continue
			}

			a.statusMsg = keyName

			if actions, ok := a.keymap.mapping[keyName]; ok {
				for _, actName := range actions {
					executeAction(a, actName)
				}
			} else if ev.Key() == tcell.KeyRune {
				r := ev.Rune()
				runes := []rune(a.query)
				a.query = string(runes[:a.caretPos]) + string(r) + string(runes[a.caretPos:])
				a.caretPos++
				a.updateFilter()
			}

			if a.cancelled || len(a.finishOutput) > 0 {
				return nil
			}

			a.drawScreen()

		case *tcell.EventResize:
			s.Sync()
			a.drawScreen()
		}
	}

	return nil
}
EOF"}

