		sm.Matched = parseStyle(specs)
	}
	if specs, ok := cfgStyle["Prompt"]; ok {
		sm.Prompt = parseStyle(specs)
	}
	if specs, ok := cfgStyle["Context"]; ok {
		sm.Context = parseStyle(specs)
	}

	return sm
}

func drawString(s tcell.Screen, x, y int, str string, style tcell.Style) int {
	for _, r := range str {
		w := runewidth.RuneWidth(r)
		s.SetContent(x, y, r, nil, style)
		x += w
	}
	return x
}
